import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse(`{"title":"I Need More Space, It's Not You It's BlueStore - Mohamad Gebai, SUSE","description":"","frontmatter":{"title":"I Need More Space, It's Not You It's BlueStore - Mohamad Gebai, SUSE","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","BlueStore","Storage Optimization","Data Distribution","Ceph Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/I_Need_More_Space_It_s_Not_You_It_s_BlueStore_-_Mohamad_Gebai_SUSE.md","filePath":"posts/2019/I_Need_More_Space_It_s_Not_You_It_s_BlueStore_-_Mohamad_Gebai_SUSE.md","lastUpdated":1780459816000}`),l={name:"posts/2019/I_Need_More_Space_It_s_Not_You_It_s_BlueStore_-_Mohamad_Gebai_SUSE.md"};function i(s,a,n,_,u,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>“空间不足，问题不在于你，而在于BlueStore的故事”</p><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（请在此处填写会议具体时间）</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>（请在此处填写会议地点）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>主讲人：Mohammed Dubai，SUSE软件工程师</li><li>与会人员：（请在此处填写与会人员名单）</li></ul><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><p><strong>1. 会议概述</strong> Mohammed Dubai分享了来自SUSE用户邮件列表的案例，探讨了用户在使用Ceph存储时遇到的空间使用问题，并深入分析了相关原因和解决方案。</p><p><strong>2. 关键案例分析</strong></p><p><strong>案例一：FDF命令分析</strong></p><ul><li><strong>问题描述</strong>：用户使用FDF命令查看空间使用情况，发现使用率高达92%，但实际可用的空间只有1.5GB。</li><li><strong>原因分析</strong>：数据分布不均，部分存储池使用率极高，导致“最大可用空间”指标不准确。</li><li><strong>解决方案</strong>：使用upmap balancer进行数据均衡，确保数据分布均匀。</li></ul><p><strong>案例二：RBD和XFS文件系统</strong></p><ul><li><strong>问题描述</strong>：用户创建了一个1TB的RBD，在XFS文件系统上使用7tf工具，发现使用了500MB空间，但删除文件后空间并未释放。</li><li><strong>原因分析</strong>：XFS文件系统的元数据占用空间，且删除文件后空间未被正确释放。</li><li><strong>解决方案</strong>：在文件系统上运行FS trim命令，释放未使用的块。</li></ul><p><strong>案例三：Rados和对象存储</strong></p><ul><li><strong>问题描述</strong>：用户使用Rados向存储池推送100个100字节的对象，发现实际存储空间使用率远高于预期。</li><li><strong>原因分析</strong>：BlueStore的最小分配单位是64KB，导致大量小对象产生大量开销。</li><li><strong>解决方案</strong>：优化应用程序，使用更大的对象或提高最小分配单位。</li></ul><p><strong>案例四：BlueStore压缩</strong></p><ul><li><strong>问题描述</strong>：启用BlueStore压缩后，发现压缩后的数据与分配到磁盘的数据存在差异。</li><li><strong>原因分析</strong>：对象过小导致压缩效率低下，产生额外开销。</li><li><strong>解决方案</strong>：使用更大的对象或优化应用程序。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>使用FDF命令时，需结合数据分布情况综合判断空间使用情况。</li><li>对于RBD和XFS文件系统，注意元数据占用空间，并定期运行FS trim命令。</li><li>优化应用程序，使用更大的对象或提高最小分配单位，提高存储效率。</li><li>启用BlueStore压缩时，注意对象大小，避免压缩效率低下。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>与会人员根据会议内容，结合自身实际情况，优化Ceph存储配置和应用设计。</li><li>针对案例中提到的问题，SUSE团队将进一步完善相关功能，提高存储效率。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议针对Ceph存储空间使用问题进行了深入探讨，分享了多个案例及解决方案，有助于与会人员更好地了解和解决空间使用问题。</p>',26)])])}const S=e(l,[["render",i]]);export{p as __pageData,S as default};
